  _ = `Este evento está publicado pero permanecerá oculto hasta la hora especificada. No se requiere ninguna acción adicional. El evento se hará automáticamente visible para tus clientes de Steam a la hora señalada.`,
  _ = `Este evento se hará visible automáticamente cuando el evento comience.`,
  _ = `Este evento se hará visible automáticamente antes de que empiece el evento. Se hará visible en %1$s`,
  _ = `Estos eventos están programados para el futuro, pero no serán visibles hasta el momento de inicio. No se requiere ninguna acción adicional. `,
  _ = `Oculto, no publicado`,
  _ = `Este evento está en modo borrador. Nadie excepto los miembros de tu equipo de la comunidad pueden verlo. Todos los cambios permanecerán ocultos hasta que tomes medidas para publicar el evento.`,
