  _ = `¡Te damos la bienvenida!`,
  _ = `<1>Tus juegos</1> - Tus juegos aparecen en la lista de aplicaciones vinculadas más abajo y están listos para usarse. Añade y configura secciones abajo para promocionar tus juegos, DLC, demos y bandas sonoras como más te convenga.`,
  _ = `<1>Vincular más juegos</1> - Si falta algún juego en esta lista, es porque no lo has vinculado con esta página de creador. Puedes consultar las instrucciones para vincularlos en la documentación sobre las <2>páginas de desarrollador y editor</2>.`,
  _ = `<1>Configuración predeterminada</1> - Más abajo verás un conjunto de secciones predeterminadas ya configuradas para destacar tus lanzamientos populares, recomendados y recientes. Utilízalas tanto o tan poco como quieras.`,
  _ = `Consulta la documentación para obtener más detalles`,
