  _ = `Esta oferta tiene una lista extensa de artículos vinculados, por lo que las etiquetas de los artículos se están regenerando desde la tienda. Esto puede tardar unos instantes.`,
  _ = `No se han podido regenerar las etiquetas de los artículos de esta oferta desde la tienda, por lo que el editor no puede abrirse de forma segura. Vuelve a cargar la página para intentarlo de nuevo.`,
  _ = `No se han podido cargar desde la tienda artículos (%1$s) de la lista de vinculados. Lo más probable es que se deba a que estén bloqueados o ya no estén a la venta. Como sus etiquetas no se han vuelto a generar, podrían dejar de mostrarse en las secciones filtradas por etiquetas (puedes seguir trabajando con normalidad si están bloqueados, etc.): %2$s.`,
