  _ = `Puedes hacer que el evento sea visible antes de la fecha de inicio si quieres que los jugadores sepan que tu evento se acerca y les permita registrarse para recibir notificaciones.`,
  _ = `Puedes hacer que el anuncio sea visible antes de la fecha de inicio si quieres que los jugadores sepan que tu evento se acerca y si quieres permitirles registrarse para recibir notificaciones.`,
