  _ = `Introduce las horas en tu zona horaria local. Estas horas se convertirán automáticamente y se mostrarán a los espectadores en su hora local.`,
  _ = `Recordatorios automáticos`,
  _ = `Al establecer que un evento empiece en el futuro Y hacerlo visible para tus fans antes, les das la opción de solicitar que se les envíe un recordatorio cuando comience el evento. Steam enviará automáticamente una notificación push o un correo electrónico a los usuarios de Steam basándose en sus preferencias.`,
  _ = `Esta prueba solo lo envía a tu cuenta si tienes un correo electrónico verificado o se ha instalado %1$s.`,
  _ = `Aplicación de Steam Mobile`,
  _ = `Prueba de notificación de evento`,
  _ = `* La característica está desactivada porque el evento no está programado para el futuro.`,
  _ = `Id. de aplicación asociado`,
  _ = `¿Quieres asociar el id. de aplicación a este evento?`,
  _ = `Esta opción permite que se asocie un id. de aplicación al evento. La cápsula de la tienda aparecerá automáticamente en la parte de abajo de la descripción del evento. Proporcionará información de la aplicación cuando sea necesario a otros widgets como el de retransmisión o el del calendario.`,
  _ = `Empieza`,
