  _ = `Seleccionar rama`,
  _ = `Elige a qué rama quieres asociar este evento para vincularlo con la compilación actual de esa rama. También puedes desvincular un evento de una compilación seleccionando la opción «No vincular este evento con una compilación».`,
  _ = `Rama «default»: Compilación %1$s (%2$s).`,
  _ = `%1$s: Compilación %2$s (%3$s)`,
  _ = `No vincular este evento con una compilación`,
  _ = `Ver historial de versiones (últimas 100\xA0entradas)`,
  _ = `Revertir evento a esta versión`,
