  _ = `Relacionado con la retransmisión`,
  _ = `Si el usuario de Steam a través de las preferencias de su cuenta oculta la retransmisión en la tienda, oculta esta sección también, ya que lo que muestra está ligado al contenido que se está retransmitiendo.`,
