  _ = `Escribe o pega el HTML aquí.`,
  _ = `Conservar saltos de línea`,
  _ = `En HTML, los cambios de línea no suelen tener efecto, pero en BBCode se muestran como líneas en blanco.  Si utilizaste etiquetas <p> o <br>, deja esto sin marcar.  Si sueles usar software para blogs que añade automáticamente etiquetas <br> para las nuevas líneas, probablemente tendrás que marcar esta casilla.`,
  _ = `Convertir a BBCode:`,
  _ = `Conversión en curso. No cierres el cuadro de diálogo.`,
