  _ = `Vista previa:`,
  _ = `Este tipo de evento se publicará automáticamente en la configuración inicial. Este tipo de evento NO tiene autorización para publicarse antes de esa hora de inicio.`,
  _ = `La publicación del evento guardará cualquier cambio y hará que el evento sea visible según lo señalado por la configuración de visibilidad.`,
  _ = `Publicar sin listar`,
  _ = `Al publicar el evento, se guardarán los cambios y el evento estará visible para quienes tengan el enlace. El evento no aparecerá en las listas de eventos, pero los clientes podrán verlo si tienen el enlace.`,
  _ = `Publicar`,
  _ = `Al publicar esta página, se guardarán los cambios y la página de creador estará visible potencialmente para quienes tengan el enlace. Los clientes podrán verla si tienen el enlace. Para configurarla como tu página de creador, también tendrás que activarla después de publicarla.`,
  _ = `¿Todo listo para guardar los cambios y luego publicar este evento?`,
  _ = `El evento se hará público inmediatamente.`,
  _ = `El evento permanecerá oculto hasta el %1$s cuando se iniciará y se hará público automáticamente.`,
  _ = `  Puedes continuar editando el contenido del evento después de la publicación.`,
  _ = `Nota: Una vez que se publica este evento, no puedes volver al estado de no publicado.`,
  _ = `¿Todo listo para guardar los cambios y publicar esta página?`,
  _ = `La página no estará visible hasta que también la establezcas como activa en el menú principal de tu página de creador.`,
  _ = `Puedes seguir editando esta página incluso después de publicarla.`,
  _ = `(Solo Valve) Como este clan tiene una asignación a un proyecto de Crowdin, al publicar se activará el envío automático de actualizaciones a Crowdin. Puedes volver a desactivar este ajuste a mano cuando quieras.`,
  _ = `Hora de publicación personalizada`,
  _ = `La hora de publicación personalizada debe estar entre ahora y la hora de inicio del evento`,
  _ = `Solo para tiempos de publicación personalizados`,
  _ = `No se puede publicar un evento sin primero guardarlo correctamente`,
  _ = `No se puede publicar hasta que no sea aprobado por Valve`,
  _ = `Usa el botón de la derecha para solicitar la revisión de la página al menos 7\xA0días antes de la fecha en que deseas publicarla para asegurarte de que hay tiempo suficiente para revisarla, aprobarla y hacer cualquier cambio necesario.`,
  _ = `Error interno en el editor, no cargamos el texto de las traducciones y bloqueamos guardar/publicar para evitar la pérdida de datos.`,
  _ = `Advertencia: El contenido del evento o anuncio fue modificado a las %1$s por el usuario %2$s. La versión que estabas editando es de las %3$s. ¿Quieres sobrescribir esos cambios?`,
  _ = `¿Quieres sobrescribir los cambios?`,
  _ = `Fallo en la publicación`,
  _ = `Publicar con advertencias`,
  _ = `Estado`,
  _ = `Por favor, espera mientras se publica...`,
  _ = `Saltar advertencias y continuar publicando...`,
  _ = `Hacer público inmediatamente una vez que se publique el evento`,
  _ = `Ocultar hasta la fecha de inicio del evento establecida arriba`,
  _ = `Ocultar hasta la hora indicada...`,
  _ = `Esto significa que los clientes de Steam podrán ver este evento inmediatamente, tan pronto como lo publiques. Esta es una opción predeterminada para anuncios o características ya lanzadas.`,
  _ = `Esto significa que el evento permanecerá oculto hasta su inicio, momento en el que se hará visible automáticamente.`,
  _ = `Después de publicar tu evento, permanecerá oculto hasta la hora especificada. Esto te permite preparar múltiples eventos futuros y hacer que aparezcan automáticamente a la hora señalada para ofrecer a tus usuarios un flujo continuo de actividades interesantes.`,
  _ = `Oculto`,
  _ = `Visible públicamente`,
  _ = `Publicado`,
  _ = `No publicado`,
  _ = `Este evento se hará público automáticamente el %1$s`,
  _ = `No se requiere ninguna acción adicional.`,
  _ = `Guardar este evento lo mantendrá en un estado oculto. Para que tus clientes de Steam vean este evento, debes publicarlo.`,
  _ = `Cualquier cambio que guardes en este evento será visible para tus clientes de Steam.`,
  _ = `Sin título`,
