  _ = `Hemos detectado un error al analizar el BBCode del cuerpo del anuncio para mostrar su vista previa: «%1$s»`,
  _ = `Este evento ya está publicado. Comenzará y se mostrará a los jugadores en %1$s.`,
  _ = `Este evento comenzará y estará visible para los jugadores el %1$s.`,
  _ = `Este evento ya está publicado. No se puede cambiar la fecha u hora de inicio de un evento publicado.`,
  _ = `El evento terminó el %1$s. La fecha de finalización de este evento no se puede modificar.`,
