  _ = `Este evento está publicado y visible desde las %1$s`,
  _ = `Editar/Migrar`,
  _ = `Este es un anuncio que se creó en una versión anterior del sistema de anuncios. No tendrá las nuevas categorías, material gráfico de títulos, ni una fecha de finalización. Si lo modificas y guardas, se migrará al nuevo sistema, lo cual te brindará soporte para esas nuevas funciones.`,
  _ = `Esto eliminará el evento de Steam y borrará todos sus metadatos (votos, comentarios, estadísticas). Si ya está visible, el evento redirigirá a una página vacía y no se recomendará a los clientes. Esta acción no es reversible.`,
  _ = `Te permite ver el evento como lo verán los clientes de Steam. Tiene una pequeña barra de vista previa en la parte superior que te permitirá cambiar de idioma fácilmente.`,
  _ = `Este evento está asociado a tu página de creador: `,
  _ = `Hora`,
