  _ = `Días`,
  _ = `Semana`,
  _ = `Semanas`,
  _ = `La fecha/hora es anterior a la hora de inicio permitida para el evento «%1$s».`,
  _ = `La fecha/hora es posterior a la hora de finalización permitida para el evento «%1$s».`,
  _ = `Este horario está reservado para %1$s. No puedes programar un evento que empiece o termine dentro del horario ya reservado. Tampoco puedes programar un evento que empiece antes y termine después del horario ya reservado.`,
  _ = `Este horario está reservado para %1$s (razón: %2$s). No puedes programar un evento que empiece o termine dentro del horario ya reservado. Tampoco puedes programar un evento que empiece antes y termine después del horario ya reservado.`,
  _ = `Franja horaria`,
  _ = `Al introducir la fecha y la hora, utiliza tu zona horaria local. Cuando se muestre a los usuarios de Steam, la hora se convertirá automáticamente a la hora local del espectador.`,
  _ = `Vaya, la hora de finalización del evento no puede ser anterior a la hora de inicio.`,
  _ = `La fecha y hora de inicio ya ha pasado`,
  _ = `La fecha y hora de inicio es anterior a la permitida`,
  _ = `La fecha y hora de inicio son posteriores a lo permitido`,
  _ = `La fecha y hora de fin son posteriores a lo permitido`,
  _ = `Resumen`,
  _ = `(Un máximo de %1$s caracteres. Aparece en las listas de eventos)`,
  _ = `(Se ha alcanzado un máximo de %1$s caracteres. Aparece en las listas de eventos)`,
  _ = `Hasta %1$s caracteres de longitud sin bbcode. Esta descripción aparecerá en las vistas de la biblioteca de Steam. El campo de la descripción corta es opcional. Si se deja en blanco, la descripción corta se generará automáticamente a partir del primer párrafo de la descripción del evento.`,
  _ = `Opcional: introduce un resumen del evento de hasta %1$s caracteres, de lo contrario se generará automáticamente.`,
  _ = `Resumen generado automáticamente: `,
  _ = `Caracteres restantes: %1$s`,
  _ = `El título del evento, que puede tener hasta%1$s caracteres. No se permite BBCode dentro del título`,
  _ = `El título de esta página para tu referencia. Solo se muestra en tu página de inicio.`,
  _ = `El subtítulo puede tener hasta %1$s caracteres, solo de texto. (No está permitido BBCode dentro de él ni otros formatos). Este subtítulo se usará junto con el título en la página de detalles del evento o del anuncio.`,
  _ = `El resumen puede tener hasta %1$s caracteres de longitud, solo texto. El resumen aparece debajo del título cuando se muestra en una lista de eventos o en el espacio destacado de eventos. Cuando no se proporciona el resumen, Steam generará automáticamente uno al extraer texto desde el comienzo de la descripción para cada idioma.`,
  _ = `Opciones`,
  _ = `Opciones especiales para grandes eventos`,
  _ = `¿Dónde más debería aparecer este evento?`,
  _ = `Visibilidad`,
  _ = `Opciones de visibilidad para este evento`,
  _ = `Página de actualización`,
  _ = `Página de creador`,
  _ = `Publicar también en el Workshop`,
  _ = `¿Es relevante esta publicación para los jugadores que visiten tu Workshop en Steam?`,
  _ = `Publicar también en la página de detalles de la demo en la biblioteca`,
  _ = `¿Es relevante esta publicación para quienes prueben tu demo?`,
  _ = `Mostrar como evento destacado en la página de detalles del juego en la biblioteca`,
  _ = `Antes de que podamos habilitarlo como destacado, asegúrate de que tengamos al menos una imagen en inglés destacada en la pestaña %1$s`,
  _ = `¿Mostrar texto automático?`,
  _ = `El título y el subtítulo del evento, junto con una superposición de oscurecimiento, se colocarán automáticamente sobre el lado derecho de la imagen.`,
  _ = `Este evento aparecerá destacado temporalmente encima de la sección de actividades de cada usuario. Esto solo debería usarse para eventos importantes, dejando tiempo suficiente entre ellos para que la página de detalles del juego no muestre siempre un evento destacado.`,
  _ = `Mostrar en la sección de novedades de la biblioteca`,
  _ = `Los jugadores verán la publicación en la sección de novedades de la biblioteca de Steam según su tiempo de juego y otros factores.`,
  _ = `Mostrar en la página de detalles del juego en la biblioteca`,
  _ = `Mostrar en la página de la tienda de Steam`,
  _ = `Considera el contenido que se mostrará a los usuarios de Steam que tengan tu juego en su biblioteca y a los que visiten tu página de producto en la tienda. Por ejemplo, no está bien incluir un enlace a otra tienda para comprar tu juego. También debes seguir las %1$s.`,
  _ = `Reglas generales de contenido de Steam`,
  _ = `Ocultar en la página principal de la biblioteca`,
  _ = `Incluye contenido solo para adultos`,
  _ = `Señala esto si la publicación incluye imágenes u otros contenidos explícitos. Esto solo está disponible para las aplicaciones marcadas como solo para adultos.`,
  _ = `Ocultar en la página de detalles del juego en la biblioteca`,
  _ = `Ocultar en la página de la tienda de Steam`,
  _ = `Configuraciones de moderación. Anula cualquier configuración de asociado.`,
  _ = `Editar restricción regional`,
  _ = `Introduce solo códigos de país de 2\xA0letras separados por comas.`,
  _ = `El tipo de evento actual, «%1$s», no se muestra en este tipo de página.`,
  _ = `Mostrar en Steam China`,
  _ = `Por defecto, los eventos no se mostrarán a los usuarios de Steam China a menos que esto esté activado.`,
  _ = `Ocultar en Steam`,
  _ = `En el caso de los eventos mostrados en Steam China, esto se puede utilizar para evitar que los usuarios globales vean el evento.`,
  _ = `El evento que se va a clonar tiene contenido en los siguientes idiomas. Marca las casillas de los idiomas que quieres mantener en el evento clonado.`,
  _ = `En la mayoría de los casos, no es buena idea clonar los idiomas existentes.`,
