  _ = `Repetir el fondo en todas las direcciones`,
  _ = `Una imagen, cubierta y difuminada`,
  _ = `Color de la flecha del carrusel`,
  _ = `Si el color de fondo o la imagen de fondo es de un color muy claro, es posible que la flecha sea difícil de ver. Usa este ajuste para anular el color blanco predeterminado de las flechas del carrusel.`,
  _ = `Si el color de fondo o la imagen de fondo es de un color muy claro, es posible que la ruta de navegación resulte difícil de ver. Usa este ajuste para anular los colores blanco y gris predeterminados de la ruta de navegación del carrusel. Esto aparece principalmente para pantallas más pequeñas, incluido el Steam\xA0Deck.`,
  _ = `Cargando información de la demo`,
  _ = `No hay ninguna demo lanzada con la que compartir esta publicación.`,
  _ = `Es necesario guardar el evento para poder compartirlo con tu demo.`,
  _ = `Cuando se publique tu evento o anuncio, aparecerá en la página de la biblioteca de la demo. Eso te permite comunicarte con los fans que solo tengan la demo. `,
  _ = `Eventos temáticos: %1$s`,
  _ = `Halloween 2022`,
  _ = `¿Este evento trata sobre actualizaciones de tu juego para Halloween 2022? Nos gustaría saber si agregas nuevos mapas, apariencias, imágenes u otro contenido a tu juego para Halloween, o si realizas eventos de tiempo limitado con contenido espeluznante especial, desafíos u otras actividades similares. Estamos evaluando mejores formas de hacer que los eventos temáticos sean más conocidos para un público más amplio, pero primero necesitamos tener una mejor idea del tipo de actividades que los desarrolladores organizan en tus juegos (si hacen alguna) para celebrar las festividades. Por favor, haz clic en «Sí» más abajo si este evento es sobre una actualización de tu juego para Halloween 2022.`,
  _ = `Eventos con temática de Halloween`,
  _ = `¿Estás organizando un evento o añadiendo contenido con temática de Halloween? Consulta la %1$s para informarte sobre la participación en el Festival del Miedo con un evento con temática de Halloween dentro del juego.`,
  _ = `Documentación de eventos de Halloween del Festival del Miedo`,
  _ = `Nuevo DLC o adición al juego`,
  _ = `Extensiones de Halloween permanentes para tu juego`,
  _ = `Anuncia un evento de Halloween de duración limitada en tu juego. Podría dar a los jugadores artículos, bonificaciones, beneficios, recompensas, experiencia, etc., adicionales. Estos eventos tienen una fecha de inicio y una fecha de finalización.`,
  _ = `Categoría de nominación para los Premios Steam`,
  _ = `Elige una categoría concreta en la que tus fans puedan nominar tu juego. ¡Podrán nominarlo en esa categoría directamente en el evento!`,
  _ = `La mayoría de las categorías de los Premios Steam son para juegos lanzados en %1$s (desde las últimas nominaciones a los Premios Steam de %2$s). Dado que tu juego se lanzó antes de esa fecha, solo podrá optar a la categoría «Con Amor y Dedicación».`,
  _ = `Para obtener más información y para descargar un kit de recursos de los Premios\xA0Steam con plantillas de diseños que podrás usar en tus materiales de marketing, consulta nuestra documentación <1>aquí</1>.`,
  _ = `Este juego no cumple los requisitos de ninguna de las categorías de los Premios\xA0Steam. Si crees que es un error, ponte en contacto con el <1>Soporte de Steamworks</1>.`,
  _ = `Confirmación de página no visible en la tienda`,
  _ = `La página de la tienda del id. de aplicación %1$s no está visible actualmente. Publicar este evento permitirá que los usuarios sepan que el juego existe. Si eliges publicar el evento de todos modos, debes confirmarlo explícitamente aquí.`,
  _ = `¿Publicar el evento aunque la página de la tienda no esté visible?`,
