  _ = `Fondo de promoción cruzada`,
  _ = `Fondo de promoción cruzada`,
  _ = `Se muestra detrás de las secciones de promoción cruzada de estas ofertas, como la sección «Descuentos y eventos». Se usa una sola imagen para todos los idiomas. Ocupa toda la sección de lado a lado y se recorta para ajustarse al tamaño, así que mantén cualquier elemento importante alejado de los bordes, sobre todo del superior y el inferior.`,
