  _ = `Esta es una lista de eventos que se han guardado y todavía los estás editando. Están ocultos para los clientes y solo los demás miembros del equipo de la comunidad de tu juego pueden verlos. Cuando estén listos, deberás publicarlos antes de que los clientes de Steam puedan verlos.`,
