  _ = `Mostrar editores objetivo`,
  _ = `Filtrar por una lista de editores o de id. de aplicación es completamente opcional. Si ninguno de los filtros está aplicado, evaluamos la configuración anterior con todos los editores en Steamworks`,
  _ = `* Mostrando %1$s`,
  _ = `Estamos utilizando el idioma alternativo %1$s, ya que el idioma %2$s elegido en la vista previa no incluye texto en la descripción del evento.`,
  _ = `Resumen de visibilidad`,
  _ = `Según tu configuración, tu evento o anuncio aparecerá en las siguientes ubicaciones`,
  _ = `Ubicaciones predeterminadas`,
  _ = `Ubicaciones opcionales`,
  _ = `Impresiones`,
  _ = `Tienda: En la página de la tienda de tu juego`,
  _ = `Este evento aparecerá en la página de la tienda de tu juego en la sección «Noticias y eventos».`,
  _ = `El número que figura aquí es la cantidad estimada de visitantes a tu página de la tienda durante el tiempo en que aparecerá el evento.`,
  _ = `Tienda: En la página «Juegos actualizados recientemente»`,
  _ = `Si utilizas una ronda de visibilidad de actualización después de publicar este evento, este aparecerá en la página «Actualizados recientemente» de los jugadores que posean o deseen tener tu juego.`,
  _ = `El número que figura aquí es la cantidad de usuarios que poseen o quieren tu juego y pueden verlo en su página «Actualizados recientemente».`,
  _ = `Noticias: En la página de noticias de tu juego`,
  _ = `Este evento aparecerá en la lista de noticias, accesible haciendo clic en «ver noticias relacionadas» en la página de la tienda de tu juego.`,
  _ = `El número refleja la cantidad estimada de tráfico a la página de noticias para tu juego.`,
  _ = `Comunidad: En el centro de la comunidad de tu juego`,
  _ = `Incluye la página principal del centro de la comunidad del juego, así como la pestaña Noticias y la vista de Anuncios vinculadas desde tu página de la tienda.`,
  _ = `Comunidad: En la fuente de actividad de los amigos de los jugadores que siguen tu juego`,
  _ = `Este evento puede aparecer en la fuente de actividades para los jugadores que siguen tu juego.`,
  _ = `El número que se muestra es el de jugadores que siguen tu juego.`,
  _ = `Futuro:`,
  _ = `Biblioteca: En la página principal de la biblioteca de Steam (potencialmente)`,
  _ = `Tus jugadores pueden ver este evento en la parte superior de la página principal de la biblioteca, dependiendo de cuántos juegos más tenga un jugador en particular y la prioridad relativa de cada anuncio o actualización.`,
  _ = `(pendiente de moderación)`,
  _ = `Biblioteca: En la sección de destacados de la página de la biblioteca de tu juego`,
  _ = `Si proporcionas una imagen para el banner de destacados, tu evento o anuncio puede aparecer justo debajo del botón «Jugar» en la página de detalles de tu juego en la biblioteca de Steam.`,
  _ = `Biblioteca: En la página de tu juego en la biblioteca de Steam de los jugadores`,
  _ = `Tu evento aparecerá en la sección de actividades de la página de tu juego dentro de la biblioteca de Steam de tus jugadores.`,
  _ = `Basado en el número de jugadores que poseen tu juego y pueden verlo en su biblioteca de Steam.`,
  _ = `En la página de Workshop`,
  _ = `También puedes publicar este evento o anuncio en Steam\xA0Workshop para tu juego. Para habilitarlo, cambia a la pestaña «Opciones» y selecciona «Publicar también en tu Workshop». Por defecto, los eventos o anuncios del juego no aparecen en la sección del Workshop.`,
  _ = `Banner de ofertas de las páginas de productos de Steam`,
  _ = `Banner de la página de producto visible desde el %1$s hasta el %2$s`,
  _ = `Puedes proporcionar un banner de ofertas en la pestaña «Ofertas», mediante el cual será posible volver a la página de las ofertas desde los juegos destacados que incluyan el banner en la parte superior de sus páginas de Steam. Esto ayuda a los clientes de Steam que se enteraron de un descuento específico a través de un mensaje de la lista de deseados o mientras navegaban por la tienda a descubrir todas las ofertas. Estos banners solo están visibles desde el inicio hasta el final del evento o durante dos semanas, lo que ocurra antes. El horario de los eventos se especifica en la pestaña «Opciones».`,
  _ = `Notificación: Correo electrónico enviado a los jugadores que siguen tu juego, o que te siguen como desarrollador o editor`,
  _ = `Esto incluye a todos los seguidores de las páginas de desarrollador, editor y franquicia asociadas a este juego.`,
  _ = `Los siguientes enlaces de desarrollador, editor o franquicia no tienen una página de creador visible. Crear una ayudaría a tus clientes a comprender lo que ofreces y les daría la oportunidad de conocer tus eventos y los nuevos lanzamientos de juegos: %1$s`,
  _ = `Noticias: Calendario de eventos personalizado para jugadores`,
  _ = `Este evento aparecerá en los Centros de noticias personalizados de los jugadores que tengan tu juego en su biblioteca, en su lista de deseados o que sigan tu juego.`,
  _ = `Notificación: <i>Push</i> móvil para los jugadores que han optado recibir tales notificaciones`,
  _ = `El número de jugadores que han solicitado explícitamente recibir un recordatorio para este evento (descargaron una entrada para un calendario externo o eligieron seguir este evento).`,
  _ = `jugadores que reciben un correo electrónico`,
  _ = `Número estimado de correos electrónicos que incluirán este evento. Periódicamente creamos un listado de eventos objetivo para cada cliente. Esto depende de la configuración de cada cliente en cuanto a las preferencias de correo electrónico y comunicación.`,
  _ = `jugadores que reciben un mensaje de marketing`,
  _ = `Número estimado de jugadores que verán este evento en su mensaje personalizado de marketing del cliente de Steam. Esta es una ventana emergente que aparece al iniciar el cliente de Steam y que muestra ofertas relevantes e información interesante sobre eventos.`,
  _ = `jugadores que han ignorado este evento`,
  _ = `El número de jugadores que han optado explícitamente por ignorar este evento.`,
  _ = `Error al cargar el evento`,
  _ = `Ver documentación`,
  _ = `Revisión de mensaje de marketing de actualización importante`,
  _ = `Una vez que el evento esté completo y no requiera más cambios, envíalo para su revisión a fin de utilizarlo en un mensaje de marketing. Puedes publicar el evento de actualización importante tan pronto como esté listo. Ten en cuenta que el proceso de revisión y aprobación puede tardar hasta %1$s\xA0días hábiles.`,
  _ = `Crea el siguiente ticket para iniciar el proceso de revisión.`,
  _ = `Crear ticket de revisión`,
  _ = `El ticket se ha enviado. Revisa y actualiza la información <1>aquí</1>.`,
  _ = `resumen`,
  _ = `Inicio de la visibilidad`,
  _ = `Una vez que lo publiques, estará visible inmediatamente en la mayoría de los sitios.`,
  _ = `Ten en cuenta que nuestro equipo de moderación revisa las publicaciones nuevas en el orden en que se publican. Las noticias o eventos pueden tardar más de una hora en aparecer en la biblioteca de Steam. Cualquier cambio en una publicación existente hará que esta vuelva a la cola de moderación.`,
  _ = `O reemplazar el contenido de un evento existente`,
  _ = `Poco común. Esto te permite ver un «borrador» del evento y reemplazar el contenido de un evento ya publicado con el contenido de este evento. Este evento desaparecerá y su contenido reemplazará el evento publicado objetivo. El tipo de evento y los ajustes de visibilidad del evento objetivo no se actualizarán.`,
  _ = `Este evento se clonó a partir de «%1$s»`,
  _ = `Reemplazar evento original`,
  _ = `El contenido de este evento sustituirá al del evento original a partir del cual se clonó.`,
  _ = `Nota: El evento original debe estar publicado y visible. No podemos reemplazarlo hasta que sea públicamente visible.`,
  _ = `Esta acción es inmediata: reemplazará el contenido del evento objetivo y será inmediatamente visible para los usuarios de Steam. El evento actual se eliminará.`,
