  _ = `Vídeo antes de la retransmisión`,
  _ = `Obsoleto: el proceso de VOD está ahora desactivado, pero se conserva por si necesitamos usar vídeos antiguos. Este vídeo se mostrará en el reproductor de retransmisiones antes de la programación normal. El VOD debe tener permisos públicos, aparte del estado de lanzamiento.`,
