  _ = `Mostrar reproductores en pantalla completa`,
  _ = `Cuando se habilita, esto elimina las columnas izquierda y derecha del reproductor. Solo es útil cuando hay una sola retransmisión para el evento y las columnas son una distracción en la experiencia.`,
  _ = `Activar el modo de reproductor en pantalla completa`,
  _ = `Cuando la opción está activa, aparece el botón para mostrar u ocultar el chat. Cuando se muestra el chat, el modo de reproductor en pantalla completa se desactiva, y se vuelve a activar cuando se cierra el chat.`,
  _ = `Permitir ocultar o mostrar el chat`,
  _ = `Mostrar anuncios de ganadores del sorteo`,
  _ = `Introducir id. del sorteo`,
  _ = `Si hay un sorteo asociado con la retransmisión y los ganadores se anuncian a través del chat de la retransmisión, al configurar el id. de grupo del sorteo, los mensajes del chat se entregarán aunque el chat esté cerrado con el fin de mostrar los anuncios.`,
  _ = `Título de la retransmisión`,
  _ = `Selecciónalo de una lista de títulos predeterminados para mostrar encima de la retransmisión en tu página de la tienda:`,
  _ = `Introducir título`,
  _ = `Ver documentación`,
  _ = `Material gráfico de la retransmisión`,
  _ = `Opciones del material gráfico de la retransmisión`,
  _ = `Mostrar las bandas derecha e izquierda en lugar de la cápsula del juego.`,
  _ = `Cuando esté activada, el banner se mostrará en la tienda de Steam, en lugar de en las cápsulas del juego. Esto es útil cuando el banner comunica más información aplicable al evento que una o varias cápsulas de aplicación específica. Y también es útil cuando varios juegos se retransmiten a lo largo del tiempo pero solo quieres mostrar recursos de un evento único.`,
  _ = `Lista de comentaristas autorizados`,
  _ = `El id. de Steam proporcionado como entrada no es válido. Este debería ser un valor de 64 bits compuesto solo por números.`,
  _ = `Fondo de la retransmisión`,
  _ = `Color interior del gradiente de fondo`,
  _ = `Color exterior del gradiente de fondo`,
  _ = `No se ha podido cargar información del usuario`,
  _ = `Configuración opcional que permite marcar para la audiencia que una retransmisión tiene un idioma hablado específico. Útil si hay múltiples retransmisiones con diferentes idiomas para este evento, lo que nos permite elegir la mejor retransmisión predeterminada para el usuario en función de su idioma.`,
  _ = `Prioridad`,
  _ = `Qué prioridad tendrá esta retransmisión sobre otras. Las de mayor prioridad se seleccionarán sobre las de menor prioridad. Si varias retransmisiones tienen la misma prioridad, se seleccionará una al azar como predeterminada.`,
