  _ = `Enviar comentarios`,
  _ = `Denunciar este artículo`,
  _ = `Por favor, describe la forma en que este artículo infringe los Términos del Servicio de Steam. Por favor, proporciona toda la información o enlaces pertinentes. El envío de este informe no se puede deshacer.`,
  _ = `Calendario`,
