  _ = `Tipo`,
  _ = `Propósito`,
  _ = `Partida vs.`,
  _ = `Este es un tipo de partida entre dos o más individuos o equipos. Una vez que acaba la partida, se puede actualizar el resultado e incluir la información del ganador.`,
  _ = `Retransmisión`,
  _ = `Esto llama a los usuarios a ver una retransmisión en vivo en Steam o en otro lugar durante este período.`,
  _ = `Jugar`,
