  _ = `En la vida real`,
  _ = `Se usa cuando la parte del calendario ocurre y está disponible para la gente en el evento, pero no se puede retransmitir en directo. Nota: Tal vez merece la pena no incluir esto en el calendario dado que tus seguidores de Steam no podrán participar en ello.`,
  _ = `Hora de inicio`,
