  _ = `Hay varios carruseles de tráileres en esta página de ofertas y tienen ajustes diferentes para la «aplicación de vídeo introductorio». Esta configuración es inusual y podría ser incorrecta.`,
  _ = `Esta aplicación no tiene ningún tráiler y no se podrá ver en esta sección.`,
