  _ = `Esta pestaña solo aparece si el usuario ha utilizado uno de estos elementos de hardware. Los usuarios que no hayan iniciado sesión no podrán ver esta sección cuando se ha seleccionador alguno de estos elementos.`,
  _ = `Lista de hardware permitido en uso`,
  _ = `Pestañas actuales`,
  _ = `Cada pestaña define una colección de artículos con un nombre asignado, que filtrará las siguientes secciones para mostrar solo esos artículos.`,
  _ = `Las pestañas son un tipo de filtro que controla qué secciones se muestran. Define aquí las pestañas y, a continuación, ve a cada sección y elige en qué pestañas debe aparecer. Por defecto, todas las secciones están visibles en todas las pestañas.`,
  _ = `Selecciona una pestaña aquí para mostrar en el editor solo las secciones que están visibles en esa pestaña. Esta característica solo está disponible durante la edición.`,
