  _ = `Color de selección/destaque`,
  _ = `Sustituye el color de selección y destaque predeterminado para las pestañas. Desmarca esta opción para volver al valor predeterminado.`,
  _ = `Lista de artículos filtrados en la pestaña`,
  _ = `Los siguientes artículos se usan como filtro, y para las siguientes secciones, solo se pueden mostrar los artículos contenidos en esta lista cuando esta pestaña está seleccionada.`,
  _ = `%1$s - Artículos: %2$s`,
  _ = `%1$s - Mostrar todos los artículos`,
  _ = `Esta pestaña está configurada para mostrar todos los artículos en las secciones que siguen. Sin embargo, al hacer clic a continuación, puedes crear una lista de artículos y luego, en las siguientes secciones, solo aparecerán los artículos contenidos en ella.`,
  _ = `Editar artículos filtrados`,
  _ = `Seleccionar imagen de fondo de pestaña (opcional)`,
  _ = `Permite establecer una imagen de fondo por pestaña que aparecerá cuando la pestaña esté seleccionada. Se extiende por toda la barra de pestañas en la parte superior de la pantalla.`,
  _ = `Nota: Al pasar el ratón, los filtros añaden automáticamente el cuadro de diálogo «Mostrar compatibilidad con Steam\xA0Deck» a las cápsulas.`,
  _ = `Nota: Al pasar el ratón, los filtros añaden automáticamente el cuadro de diálogo sobre la compatibilidad con Steam\xA0Frame a las cápsulas.`,
  _ = `Nota: Al pasar el ratón, los filtros añaden automáticamente el cuadro de diálogo sobre la compatibilidad con Steam\xA0Machine a las cápsulas.`,
