  _ = `Nota: Los filtros esconden esta pestaña automáticamente a los usuarios que no permiten que Steam les muestre contenido que es solo para adultos.`,
  _ = `Nota: El filtro eliminará automáticamente las pestañas no relacionadas con próximos eventos del explorador de artículos.`,
  _ = `Lista de accesos directos`,
  _ = `Las listas de accesos directos aparecen debajo de las pestañas y sirven para ir rápidamente a cada sección, lo cual resulta útil cuando la pestaña incluye muchas secciones.`,
