  _ = `Nueva pestaña`,
  _ = `Abre la vista previa en tiempo real en una ventana emergente del navegador. Si no está seleccionado, se abrirá en una nueva pestaña, lo que facilita usar las herramientas de desarrollador y habilita funciones como el modo para dispositivos móviles de dichas herramientas.`,
