  _ = `Suscripción - Precio`,
  _ = `Calendario de eventos`,
  _ = `El calendario de eventos extrae y muestra automáticamente los eventos de los juegos destacados para que aparezcan en la página de rebajas, ordenados por su hora de inicio. Es útil para mostrar las retransmisiones que habrá durante las rebajas.`,
