  _ = `Preguntas condicionales`,
  _ = `Después de la primera pregunta, todas las preguntas siguientes dependen de la respuesta anterior. Es decir, el usuario no ve todas las preguntas y las respuestas elegidas determinan la pregunta que aparece a continuación.`,
