  _ = `Desactiva la variante para tabletas y borra sus parámetros.`,
  _ = `La variante para tabletas es un ajuste opcional que permite personalizar completamente esta cuadrícula de contenido multimedia con diferentes textos, imágenes y controles específicos para la visualización en tabletas o Steam\xA0Deck y dispositivos similares.`,
