  _ = `Nombre de la insignia`,
  _ = `Descripción inicial de la insignia`,
  _ = `Describe la mecánica básica para obtener la insignia a quienes no la hayan recibido todavía. La descripción se mostrará también a los usuarios que no hayan iniciado sesión y se les pedirá que inicien sesión para conseguir la insignia.`,
  _ = `Instrucciones de progreso de la insignia`,
  _ = `Ahora que el usuario tiene la insignia inicial, se puede hacer esta sugerencia adicional para ayudarle a subir la insignia al siguiente nivel.`,
  _ = `Instrucciones de progreso de la insignia - Máximo nivel alcanzado`,
  _ = `Este es el nivel máximo de insignia que sospechamos que el cliente medio podría alcanzar de manera razonable. Las instrucciones podrían sugerir otras acciones para seguir subiendo de nivel si existe esa posibilidad. `,
  _ = `URL y niveles de la insignia`,
  _ = `Nivel`,
  _ = `URL de la imagen de una insignia`,
  _ = `El recurso normalmente existe en la comunidad y debe ser de 160\xA0×\xA0160 píxeles. Puedes usar la ruta corta {IMG_URL}/badges/... para hacer referencia a la imagen.`,
  _ = `(Opcional) URL de la imagen de una insignia fantasma`,
  _ = `Los recursos opcionales, si se establecen, se mostrarán al usuario ANTES de adquirir la insignia real. Esto es útil cuando quieres ocultar detalles específicos sobre la insignia antes de que sea adquirida. Estos recursos deben ser de 160\xA0×\xA0160 píxeles.`,
  _ = `Añadir línea de nivel y URL`,
  _ = `Id. de la insignia del usuario (específica del evento)`,
  _ = `Al completar las listas de descubrimientos de esta página de ofertas, se conceden niveles de la insignia.`,
  _ = `Para ello, debe existir una lista de descubrimientos en la página de las rebajas. La insignia se actualizará de forma dinámica cuando se completa una lista y las recompensas obtenidas se reflejarán en la página del resumen de la lista de descubrimientos.`,
  _ = `Editor de progreso de misiones`,
