  _ = `Grupo de artículos`,
  _ = `A qué grupo pertenece este artículo. Al abrir una puerta, se obtiene un artículo de cada uno de los grupos que cubra. Por lo tanto, si un grupo contiene varios artículos, solo se obtiene uno de ellos, elegido al azar. Incluye cada artículo en un grupo diferente, a menos que quieras que solo se puedan obtener de forma alternativa.`,
